Given an array arr[] of size n, construct another array res[] of size n such that res[i] is equal to the XOR of all elements of arr[] except arr[i].Examples:Input: arr[] = [2, 1, 5, 9]Output: [13, 14, 10, 6]Explanation: res[0] = 1 ^ 5 ^ 9 = 13res[1] = 2 ^ 5 ^ 9 = 14res[2] = 2 ^ 1 ^ 9 = 10res[3] = 2 ^ 1 ^ 5 = 6Therefore, the resulting array is [13, 14, 10, 6].Input: arr[] = [2, 1]Output: [1, 2]Explanation: res[0] = 1res[1] = 2Since only one element remains after excluding the current element, each position contains that remaining element. Therefore, the resulting array is [1, 2].Try It YourselfTable of Content[Naive Approach] Simple Simulation - O(n ^ 2) Time and O(n) Space[Better Approach] Prefix XOR and Suffix XOR - O(n) Time and O(n) Space[Expected Approach] Using XOR Property - O(n) Time and O(1) Space[Naive Approach] Simple Simulation - O(n ^ 2) Time and O(n) SpaceFor every index i, calculate the XOR of all elements except arr[i]. To do this, traverse the entire array again in an inner loop and XOR every element except the current one.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> getXor(vector<int>& arr) {
    int n = arr.size();

    vector<int> res(n);

    for (int i = 0; i < n; i++) {
        int currXor = 0;

        for (int j = 0; j < n; j++) {
            if (i != j) {
                currXor ^= arr[j];
            }
        }

        res[i] = currXor;
    }

    return res;
}

int main() {
    vector<int> arr1 = {2, 1, 5, 9};
    vector<int> res1 = getXor(arr1);

    for (int x : res1) {
        cout << x << " ";
    }
    cout << endl;

    vector<int> arr2 = {2, 1};
    vector<int> res2 = getXor(arr2);

    for (int x : res2) {
        cout << x << " ";
    }

    return 0;
}


