            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> getXor(vector<int>& arr) {
    int n = arr.size();

    vector<int> prefix(n), suffix(n), res(n);

    prefix[0] = arr[0];

    for (int i = 1; i < n; i++) {
        prefix[i] = prefix[i - 1] ^ arr[i];
    }

    suffix[n - 1] = arr[n - 1];

    for (int i = n - 2; i >= 0; i--) {
        suffix[i] = suffix[i + 1] ^ arr[i];
    }

    for (int i = 0; i < n; i++) {
        int left = (i > 0) ? prefix[i - 1] : 0;
        int right = (i < n - 1) ? suffix[i + 1] : 0;

        res[i] = left ^ right;
    }

    return res;
}

