vector<int> getXor(vector<int>& arr) {
    int totalXor = 0;

    for (int x : arr) {
        totalXor ^= x;
    }

    vector<int> res(arr.size());

    for (int i = 0; i < arr.size(); i++) {
        res[i] = totalXor ^ arr[i];
    }

    return res;
}

